<template>
  <section class="demo-page">
    <p class="eyebrow">WAREHOUSE LAB / LOCAL DATA WORKSPACE</p>
    <h1>从源数据到可核验的数仓</h1>
    <p>导入自己的 CSV，执行五层建模，定位质量异常，再对比两次运行。当前使用固定电商模型与 SQLite 实际执行；Live Agent 仍在独立工作台。</p>
    <div class="mode-switch"><button :class="{active:mode==='synthetic'}" @click="mode='synthetic'">合成数据</button><button :class="{active:mode==='csv'}" @click="mode='csv'">导入 CSV</button><a href="/api/demo/template.zip">下载五表模板 ZIP ↗</a></div>
    <div v-if="mode==='synthetic'" class="controls"><label>订单数<input v-model.number="orders" type="number" min="1" max="10000"></label><label>随机种子<input v-model.number="seed" type="number"></label><button :disabled="busy" @click="execute">{{busy?'正在执行…':'运行离线演示'}}</button></div>
    <div v-else class="import-panel" @dragover.prevent @drop.prevent="loadFiles($event.dataTransfer.files)"><strong>选择或拖入五份 UTF-8 CSV</strong><p>customers、products、orders、order_items、payments；总计最多 4 MiB，金额列使用整数分。表头、主外键和类型会先校验。</p><input type="file" multiple accept=".csv" aria-label="导入五份CSV" @change="loadFiles($event.target.files)"><ul><li v-for="name in sourceNames" :key="name">{{files[name]?'✓':'○'}} {{name}}.csv</li></ul><button :disabled="busy || !filesReady" @click="execute">{{busy?'正在执行…':'导入并建模'}}</button></div>
    <p v-if="error" class="error" role="alert">{{error}}</p>
    <details class="history-panel" open><summary>运行历史与对比 <small>{{history.length}} 条 · 最多显示最近 100 条</small></summary><div class="controls"><select v-model="left" aria-label="基准运行"><option value="">选择基准运行</option><option v-for="r in history" :value="r.run_id">{{r.run_id}} · {{r.source_orders}}订单 · {{r.status}}</option></select><select v-model="right" aria-label="对照运行"><option value="">选择对照运行</option><option v-for="r in history" :value="r.run_id">{{r.run_id}} · {{r.source_orders}}订单 · {{r.status}}</option></select><button :disabled="!left || !right || left===right || busy" @click="compare">比较运行</button></div><div class="history-list"><button v-for="r in history" :key="r.run_id" :disabled="busy" @click="openRun(r.run_id)"><span :class="r.status==='passed'?'passed':'error'">{{r.passed}}/{{r.checks}}</span> {{r.source_mode==='csv'?'CSV':'合成'}} · {{r.source_orders}} 订单 <small>{{r.run_id}}</small></button></div><p v-if="!history.length">首次运行后，结果会持久保存在本机。</p></details>
    <section v-if="comparison" class="comparison"><h2>两次运行的实际差异</h2><p>{{comparison.left}} → {{comparison.right}}</p><p>{{comparison.limitation}}</p><div class="table-wrap"><table><thead><tr><th>指标</th><th>基准</th><th>对照</th><th>差值</th></tr></thead><tbody><tr v-for="m in comparison.metrics" :key="m.metric"><td>{{m.metric}}</td><td>{{m.left}}</td><td>{{m.right}}</td><td>{{m.delta}}</td></tr><tr v-for="r in comparison.row_counts" :key="r.table"><td>{{r.table}} 行数</td><td>{{r.left}}</td><td>{{r.right}}</td><td>{{r.delta}}</td></tr></tbody></table></div><p>检查结果变化：{{comparison.changed_checks.length}} 项；源 CSV 指纹变化：{{comparison.source_changes.filter(x=>x.changed).map(x=>x.table).join('、') || '无 / 合成数据无CSV指纹'}}</p></section>
    <template v-if="report">
      <div class="stats"><article><strong>{{report.models.length}}</strong><span>已落表模型</span></article><article><strong>{{report.checks.filter(c=>c.passed).length}}/{{report.checks.length}}</strong><span>质量检查通过</span></article><article><strong>{{report.source_orders}}</strong><span>{{report.synthetic?'合成':'导入'}}订单</span></article><article><strong>{{report.elapsed_ms?.toFixed(1) ?? '—'}}<small> ms</small></strong><span>源数据到诊断实测耗时</span></article></div>
      <div class="controls"><span>运行 {{report.run_id}} · <b :class="report.status==='passed'?'passed':'error'">{{report.status}}</b></span><a :href="runUrl+'/export.zip'">下载完整产物 ZIP</a><a :href="runUrl+'/artifacts/warehouse.sql'">SQL</a><a :href="runUrl+'/artifacts/report.json'">JSON</a><a :href="runUrl+'/artifacts/report.html'">HTML报告</a></div>
      <nav class="tabs" aria-label="运行结果"><button v-for="(label,key) in tabs" :key="key" :class="{active:tab===key}" @click="changeTab(key)">{{label}}</button></nav>
      <section v-if="tab==='models'" class="models"><article v-for="m in report.models" :key="m.name"><small>{{m.layer}}</small><h3>{{m.name}}</h3><p>{{report.row_counts[m.name]}} 行 · {{m.grain.join(' × ')}}</p><details><summary>查看执行的 SELECT</summary><pre>{{m.select}}</pre></details><button class="subtle" @click="selectTable(m.name)">查看实际数据</button></article></section>
      <section v-if="tab==='data'"><h2>只读数据预览</h2><div class="controls"><select v-model="table" @change="loadPreview(0)" aria-label="选择数据表"><optgroup label="源数据"><option v-for="name in sourceNames" :value="name">{{name}}</option></optgroup><optgroup label="已落表模型"><option v-for="m in report.models" :value="m.name">{{m.name}}</option></optgroup></select><button :disabled="!preview || preview.offset===0" @click="loadPreview(Math.max(0,preview.offset-25))">上一页</button><button :disabled="!preview || preview.offset+25>=preview.total" @click="loadPreview(preview.offset+25)">下一页</button><span v-if="preview">{{preview.total}} 行 · 当前 {{preview.offset+1}}—{{Math.min(preview.offset+25,preview.total)}}</span></div><div class="table-wrap" v-if="preview"><table><thead><tr><th v-for="column in preview.columns">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in preview.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{cell ?? 'NULL'}}</td></tr></tbody></table></div></section>
      <section v-if="tab==='quality'"><div class="controls"><h2>质量检查与诊断</h2><button :disabled="busy" @click="diagnose">重新只读检查</button></div><p v-if="diagnostics">{{diagnostics.guidance}}</p><p v-if="diagnostics?.snapshot_unchanged!==undefined">数据库与初始快照：{{diagnostics.snapshot_unchanged===null?'旧记录无指纹':diagnostics.snapshot_unchanged?'一致':'已变化'}}；本次检查 {{diagnostics.status}}</p><p v-if="diagnostics?.affected_models.length">影响模型：{{diagnostics.affected_models.join(' → ')}}</p><div class="table-wrap"><table><thead><tr><th>检查</th><th>结果</th><th>实际值</th><th>期望值</th></tr></thead><tbody><tr v-for="c in (diagnostics?.checks || report.checks)" :key="c.name"><td>{{c.name}}</td><td :class="c.passed?'passed':'error'">{{c.passed?'通过':'失败'}}</td><td>{{c.actual}}</td><td>{{c.expected}}</td></tr></tbody></table></div><template v-if="diagnostics?.order_mismatches.length"><h3>金额不一致的订单证据（最多 20 条，共 {{diagnostics.order_mismatch_count}} 条）</h3><div class="table-wrap"><table><thead><tr><th>订单</th><th>应收/分</th><th>实收/分</th><th>差额/分</th></tr></thead><tbody><tr v-for="row in diagnostics.order_mismatches" :key="row.order_id"><td>{{row.order_id}}</td><td>{{row.gross_cents}}</td><td>{{row.paid_cents}}</td><td>{{row.delta_cents}}</td></tr></tbody></table></div></template></section>
      <section v-if="tab==='lineage'"><h2>表级血缘与每日销售</h2><div class="lineage"><span v-for="layer in ['SOURCE','ODS','DIM','DWD','DWS','ADS']" :key="layer">{{layer}}</span></div><ul><li v-for="edge in report.lineage" :key="edge.source+edge.target"><code>{{edge.source}}</code> → <code>{{edge.target}}</code></li></ul><div class="table-wrap"><table><thead><tr><th>日期</th><th>订单数</th><th>应收金额</th><th>实收金额</th></tr></thead><tbody><tr v-for="row in report.daily_sales" :key="row.order_date"><td>{{row.order_date}}</td><td>{{row.order_count}}</td><td>{{formatCents(row.gross_cents)}}</td><td>{{formatCents(row.paid_cents)}}</td></tr></tbody></table></div></section>
      <section v-if="tab==='trace'"><h2>执行轨迹与来源</h2><p>只记录实际阶段、耗时与公开结果；不记录模型隐藏思维。以下链路不调用 LLM。</p><div class="table-wrap"><table><thead><tr><th>阶段</th><th>状态</th><th>耗时/ms</th><th>结果</th></tr></thead><tbody><tr v-for="step in report.trace || []" :key="step.stage"><td>{{step.stage}}</td><td>{{step.status}}</td><td>{{step.elapsed_ms}}</td><td>{{step.summary}}</td></tr></tbody></table></div><p class="digest">数据库 SHA-256：{{report.database_sha256 || '旧记录未保存'}}</p><ul><li v-for="source in report.source_manifest || []" :key="source.table" class="digest">{{source.table}} · {{source.rows}} 行 · {{source.sha256}}</li></ul></section>
    </template>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { formatCents } from '../utils/money.js'
const sourceNames=['customers','products','orders','order_items','payments']
const tabs={models:'分层模型',data:'数据预览',quality:'质量与诊断',lineage:'血缘与销售',trace:'执行轨迹'}
const orders=ref(120),seed=ref(7),mode=ref('synthetic'),files=ref({}),busy=ref(false),error=ref(''),report=ref(null),history=ref([]),left=ref(''),right=ref(''),comparison=ref(null),tab=ref('models'),table=ref('dwd_order'),preview=ref(null),diagnostics=ref(null)
const filesLoading=ref(false)
const filesReady=computed(()=>!filesLoading.value && sourceNames.every(n=>typeof files.value[n]==='string'))
const runUrl=computed(()=>report.value?'/api/demo/runs/'+encodeURIComponent(report.value.run_id):'')
let selectedVersion=0,previewVersion=0,compareVersion=0,filesVersion=0
async function request(url,options){const response=await fetch(url,options);const value=await response.json();if(!response.ok && !(response.status===422 && value.models))throw new Error(value.detail || '本地操作失败');return value}
async function loadFiles(list){const version=++filesVersion;files.value={};filesLoading.value=true;error.value='';try{const values=[...list];if(values.length!==5 || new Set(values.map(f=>f.name)).size!==5)throw new Error('请选择五份名称不重复的模板 CSV');if(values.reduce((sum,f)=>sum+f.size,0)>4*1024*1024)throw new Error('CSV 总大小不能超过 4 MiB');const next={};for(const file of values){const name=file.name.replace(/\.csv$/i,'');if(!sourceNames.includes(name))throw new Error('文件名必须与五表模板一致');next[name]=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer())}if(version===filesVersion)files.value=next}catch(exc){if(version===filesVersion){files.value={};error.value=exc.message}}finally{if(version===filesVersion)filesLoading.value=false}}
function showReport(value){selectedVersion++;previewVersion++;report.value=value;diagnostics.value=value.diagnostics || null;preview.value=null;table.value='dwd_order';tab.value=value.status==='failed'?'quality':'models'}
async function refresh(){history.value=await request('/api/demo/runs')}
async function execute(){if(busy.value || (mode.value==='csv' && !filesReady.value))return;busy.value=true;error.value='';const version=++selectedVersion;try{const imported=mode.value==='csv';const value=await request(imported?'/api/demo/import':'/api/demo/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(imported?{tables:files.value}:{orders:orders.value,seed:seed.value})});if(version===selectedVersion)showReport(value);await refresh()}catch(exc){error.value=exc.message}finally{busy.value=false}}
async function openRun(id){const version=++selectedVersion;previewVersion++;error.value='';try{const value=await request('/api/demo/runs/'+encodeURIComponent(id));if(version===selectedVersion)showReport(value)}catch(exc){if(version===selectedVersion)error.value=exc.message}}
async function loadPreview(offset=0){const version=++previewVersion,id=report.value?.run_id,name=table.value;preview.value=null;try{const value=await request('/api/demo/runs/'+encodeURIComponent(id)+'/tables/'+encodeURIComponent(name)+'?offset='+offset);if(version===previewVersion && report.value?.run_id===id && table.value===name)preview.value=value}catch(exc){if(version===previewVersion)error.value=exc.message}}
function changeTab(key){tab.value=key;if(key==='data' && !preview.value)loadPreview(0)}
function selectTable(name){table.value=name;tab.value='data';loadPreview(0)}
async function compare(){const version=++compareVersion;error.value='';try{const value=await request('/api/demo/compare?left='+encodeURIComponent(left.value)+'&right='+encodeURIComponent(right.value));if(version===compareVersion)comparison.value=value}catch(exc){if(version===compareVersion)error.value=exc.message}}
async function diagnose(){const id=report.value.run_id;busy.value=true;error.value='';try{const value=await request(runUrl.value+'/diagnose',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(report.value?.run_id===id)diagnostics.value=value}catch(exc){error.value=exc.message}finally{busy.value=false}}
onMounted(()=>refresh().catch(exc=>{error.value=exc.message}))
</script>
<style scoped>
.demo-page{max-width:1180px;margin:40px auto;padding:0 24px 80px}.eyebrow{font-size:12px;letter-spacing:.2em;color:var(--color-accent,#087f8c)}h1{font-size:clamp(30px,4vw,48px);letter-spacing:-.03em;margin:16px 0}h2{margin:24px 0 16px}p{line-height:1.8;color:var(--color-text-secondary,#546374)}.controls,.mode-switch,.tabs{display:flex;gap:14px;flex-wrap:wrap;align-items:center;margin:24px 0}label{display:grid;gap:6px}input,select{padding:10px;border:1px solid #8b9da5;border-radius:8px;color:inherit;background:var(--color-bg-elevated,#f7fafb);max-width:100%}input[type=number]{width:130px}select{max-width:320px}button{padding:11px 18px;border:0;border-radius:8px;background:var(--color-accent,#087f8c);color:white;cursor:pointer}button:disabled{opacity:.5;cursor:default}.mode-switch button,.tabs button,.subtle{background:transparent;color:var(--color-accent,#087f8c);border:1px solid #8b9da5}.active{background:var(--color-accent,#087f8c)!important;color:white!important}a{color:var(--color-accent,#087f8c);font-size:14px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:32px}.stats article,.models article,.import-panel,.history-panel,.comparison{border:1px solid #8b9da5;border-radius:12px;padding:20px}.stats strong{display:block;font-size:30px}.stats span,small{color:var(--color-accent,#087f8c)}.models{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}h3{font-size:17px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.6}summary{cursor:pointer;color:var(--color-accent,#087f8c)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border-bottom:1px solid #8b9da5;padding:10px;text-align:left;white-space:nowrap}.passed{color:#149660}.error{color:#db5b4e}li{padding:5px 0}code{font-size:13px}.history-list{display:flex;gap:8px;overflow:auto;max-height:150px}.history-list button{background:transparent;border:1px solid #8b9da5;color:inherit;flex:0 0 auto;text-align:left}.history-list small{display:block;margin-top:6px;font-size:10px}.import-panel ul{display:flex;flex-wrap:wrap;list-style:none;gap:20px;padding:0}.digest{font-family:monospace;overflow-wrap:anywhere;font-size:12px}.lineage{display:flex;gap:10px;flex-wrap:wrap}.lineage span{background:var(--color-accent,#087f8c);color:white;padding:12px;border-radius:6px}@media(max-width:750px){.stats{grid-template-columns:repeat(2,1fr)}.controls{gap:10px}.demo-page{padding:0 16px 40px}.history-panel{padding:14px}}@media(max-width:420px){.stats{grid-template-columns:1fr}}
</style>
